trait Service { def call(r: Request): Response }

trait Gate extends Service {                    // one gate per boundary
  protected def inner: Service                  // the next gate in the chain
  protected def rule: Rule
  override def call(r: Request): Response = {
    val id = verify(r)                          // this gate's own evidence
    if (!rule.allows(id, r)) throw Forbidden    // fail closed
    inner.call(r)                               // delegate inward
  }
}
